<main class="scanner-page"><div class="scanner-header"><a class="brand" href="<?= base_url('scanner') ?>"><span class="brand-mark">S</span><span>EUPHORIA <strong>SCAN</strong></span></a><div class="scanner-user"><span class="user-dot"></span><?= esc(session('user_name')) ?><a href="<?= base_url('scanner/logout') ?>">↗</a></div></div><div class="scanner-main"><div class="scanner-title"><span class="eyebrow accent">AUTHORIZED ENTRY / LIVE</span><h1>Ready<br><em>when you are.</em></h1><p>Choose an event, day and gate, then scan the QR on the participant’s pass.</p></div><div class="scanner-controls"><label>Event<select id="scan-event" data-testid="scanner-event-select"><option value="">Select event</option><?php foreach ($events as $event): ?><option value="<?= esc($event['id']) ?>"><?= esc($event['name']) ?></option><?php endforeach ?></select></label><label>Event day<select id="scan-day" data-testid="scanner-day-select"><option value="">Select day</option><?php foreach ($days as $day): ?><option value="<?= esc($day['id']) ?>" data-event="<?= esc($day['event_id']) ?>"><?= esc($day['label']) ?> · <?= esc($day['event_date']) ?></option><?php endforeach ?></select></label><label>Gate<select id="scan-gate" data-testid="scanner-gate-select"><option value="">Select gate</option><?php foreach ($gates as $gate): ?><option value="<?= esc($gate['id']) ?>"><?= esc($gate['name']) ?></option><?php endforeach ?></select></label><div class="scan-input-wrap"><label>Secure token<input id="scan-token" placeholder="Paste QR token for a test scan" data-testid="scanner-token-input"></label><button id="scan-submit" class="button button-yellow" type="button" data-testid="scanner-submit-button">Validate entry <span>↗</span></button></div></div><div id="scan-result" class="scan-result" data-testid="scanner-result"><span class="scan-icon">⌁</span><strong>Waiting for a scan</strong><span>Select the assignment above to begin.</span></div></div></main>